357	func parseOptAdmin(d *caddyfile.Dispenser, _ any) (any, error) {
358		d.Next() // consume option name
359	
360		adminCfg := new(caddy.AdminConfig)
361		if d.NextArg() {
362			listenAddress := d.Val()
363			if listenAddress == "off" {
364				adminCfg.Disabled = true
365				if d.Next() { // Do not accept any remaining options including block
366					return nil, d.Err("No more option is allowed after turning off admin config")
367				}
368			} else {
369				adminCfg.Listen = listenAddress
370				if d.NextArg() { // At most 1 arg is allowed
371					return nil, d.ArgErr()
372				}
373			}
374		}
375		for d.NextBlock(0) {
376			switch d.Val() {
377			case "enforce_origin":
378				adminCfg.EnforceOrigin = true
379	
380			case "origins":
381				adminCfg.Origins = d.RemainingArgs()
382	
383			default:
384				return nil, d.Errf("unrecognized parameter '%s'", d.Val())
385			}
386		}
387		if adminCfg.Listen == "" && !adminCfg.Disabled {
388			adminCfg.Listen = caddy.DefaultAdminListen
389		}
390		return adminCfg, nil
391	}
