393	func parseOptOnDemand(d *caddyfile.Dispenser, _ any) (any, error) {
394		d.Next() // consume option name
395		if d.NextArg() {
396			return nil, d.ArgErr()
397		}
398	
399		var ond *caddytls.OnDemandConfig
400	
401		for nesting := d.Nesting(); d.NextBlock(nesting); {
402			switch d.Val() {
403			case "ask":
404				if !d.NextArg() {
405					return nil, d.ArgErr()
406				}
407				if ond == nil {
408					ond = new(caddytls.OnDemandConfig)
409				}
410				if ond.PermissionRaw != nil {
411					return nil, d.Err("on-demand TLS permission module (or 'ask') already specified")
412				}
413				perm := caddytls.PermissionByHTTP{Endpoint: d.Val()}
414				ond.PermissionRaw = caddyconfig.JSONModuleObject(perm, "module", "http", nil)
415	
416			case "permission":
417				if !d.NextArg() {
418					return nil, d.ArgErr()
419				}
420				if ond == nil {
421					ond = new(caddytls.OnDemandConfig)
422				}
423				if ond.PermissionRaw != nil {
424					return nil, d.Err("on-demand TLS permission module (or 'ask') already specified")
425				}
426				modName := d.Val()
427				modID := "tls.permission." + modName
428				unm, err := caddyfile.UnmarshalModule(d, modID)
429				if err != nil {
430					return nil, err
431				}
432				perm, ok := unm.(caddytls.OnDemandPermission)
433				if !ok {
434					return nil, d.Errf("module %s (%T) is not an on-demand TLS permission module", modID, unm)
435				}
436				ond.PermissionRaw = caddyconfig.JSONModuleObject(perm, "module", modName, nil)
437	
438			case "interval":
439				return nil, d.Errf("the on_demand_tls 'interval' option is no longer supported, remove it from your config")
440	
441			case "burst":
442				return nil, d.Errf("the on_demand_tls 'burst' option is no longer supported, remove it from your config")
443	
444			default:
445				return nil, d.Errf("unrecognized parameter '%s'", d.Val())
446			}
447		}
448		if ond == nil {
449			return nil, d.Err("expected at least one config parameter for on_demand_tls")
450		}
451		return ond, nil
452	}
