528	// parseLogOptions parses the global log option. Syntax:
529	//
530	//	log [name] {
531	//	    output  <writer_module> ...
532	//	    format  <encoder_module> ...
533	//	    level   <level>
534	//	    include <namespaces...>
535	//	    exclude <namespaces...>
536	//	}
537	//
538	// When the name argument is unspecified, this directive modifies the default
539	// logger.
540	func parseLogOptions(d *caddyfile.Dispenser, existingVal any) (any, error) {
541		currentNames := make(map[string]struct{})
542		if existingVal != nil {
543			innerVals, ok := existingVal.([]ConfigValue)
544			if !ok {
545				return nil, d.Errf("existing log values of unexpected type: %T", existingVal)
546			}
547			for _, rawVal := range innerVals {
548				val, ok := rawVal.Value.(namedCustomLog)
549				if !ok {
550					return nil, d.Errf("existing log value of unexpected type: %T", existingVal)
551				}
552				currentNames[val.name] = struct{}{}
553			}
554		}
555	
556		var warnings []caddyconfig.Warning
557		// Call out the same parser that handles server-specific log configuration.
558		configValues, err := parseLogHelper(
559			Helper{
560				Dispenser: d,
561				warnings:  &warnings,
562			},
563			currentNames,
564		)
565		if err != nil {
566			return nil, err
567		}
568		if len(warnings) > 0 {
569			return nil, d.Errf("warnings found in parsing global log options: %+v", warnings)
570		}
571	
572		return configValues, nil
573	}
