580	func parseOptDNS(d *caddyfile.Dispenser, _ any) (any, error) {
581		d.Next() // consume option name
582		optName := d.Val()
583	
584		// get DNS module name
585		if !d.Next() {
586			// this is allowed if this is the "acme_dns" option since it may refer to the globally-configured "dns" option's value
587			if optName == "acme_dns" {
588				return nil, nil
589			}
590			return nil, d.ArgErr()
591		}
592		modID := "dns.providers." + d.Val()
593		unm, err := caddyfile.UnmarshalModule(d, modID)
594		if err != nil {
595			return nil, err
596		}
597		switch unm.(type) {
598		case libdns.RecordGetter,
599			libdns.RecordSetter,
600			libdns.RecordAppender,
601			libdns.RecordDeleter:
602		default:
603			return nil, d.Errf("module %s (%T) is not a libdns provider", modID, unm)
604		}
605		return unm, nil
606	}
