608	func parseOptECH(d *caddyfile.Dispenser, _ any) (any, error) {
609		d.Next() // consume option name
610	
611		ech := new(caddytls.ECH)
612	
613		publicNames := d.RemainingArgs()
614		for _, publicName := range publicNames {
615			ech.Configs = append(ech.Configs, caddytls.ECHConfiguration{
616				PublicName: publicName,
617			})
618		}
619		if len(ech.Configs) == 0 {
620			return nil, d.ArgErr()
621		}
622	
623		for nesting := d.Nesting(); d.NextBlock(nesting); {
624			switch d.Val() {
625			case "dns":
626				if !d.Next() {
627					return nil, d.ArgErr()
628				}
629				providerName := d.Val()
630				modID := "dns.providers." + providerName
631				unm, err := caddyfile.UnmarshalModule(d, modID)
632				if err != nil {
633					return nil, err
634				}
635				ech.Publication = append(ech.Publication, &caddytls.ECHPublication{
636					Configs: publicNames,
637					PublishersRaw: caddy.ModuleMap{
638						"dns": caddyconfig.JSON(caddytls.ECHDNSPublisher{
639							ProviderRaw: caddyconfig.JSONModuleObject(unm, "name", providerName, nil),
640						}, nil),
641					},
642				})
643			default:
644				return nil, d.Errf("ech: unrecognized subdirective '%s'", d.Val())
645			}
646		}
647	
648		return ech, nil
649	}
650	
651	func parseOptRenewalWindowRatio(d *caddyfile.Dispenser, _ any) (any, error) {
652		d.Next() // consume option name
653		if !d.Next() {
654			return 0, d.ArgErr()
655		}
656		val := d.Val()
657		ratio, err := strconv.ParseFloat(val, 64)
658		if err != nil {
659			return 0, d.Errf("parsing renewal_window_ratio: %v", err)
660		}
661		if ratio <= 0 || ratio >= 1 {
662			return 0, d.Errf("renewal_window_ratio must be between 0 and 1 (exclusive)")
663		}
664		if d.Next() {
665			return 0, d.ArgErr()
666		}
667		return ratio, nil
668	}
