38	func init() {
39		caddyconfig.RegisterAdapter("caddyfile", caddyfile.Adapter{ServerType: ServerType{}})
40	}
41	
42	// App represents the configuration for a non-standard
43	// Caddy app module (e.g. third-party plugin) which was
44	// parsed from a global options block.
45	type App struct {
46		// The JSON key for the app being configured
47		Name string
48	
49		// The raw app config as JSON
50		Value json.RawMessage
51	}
52	
53	// ServerType can set up a config from an HTTP Caddyfile.
54	type ServerType struct{}
55	
56	// Setup makes a config from the tokens.
57	func (st ServerType) Setup(
58		inputServerBlocks []caddyfile.ServerBlock,
59		options map[string]any,
60	) (*caddy.Config, []caddyconfig.Warning, error) {
61		var warnings []caddyconfig.Warning
62		gc := counter{new(int)}
63		state := make(map[string]any)
64	
65		// load all the server blocks and associate them with a "pile" of config values
66		originalServerBlocks := make([]serverBlock, 0, len(inputServerBlocks))
67		for _, sblock := range inputServerBlocks {
68			for j, k := range sblock.Keys {
69				if j == 0 && strings.HasPrefix(k.Text, "@") {
70					return nil, warnings, fmt.Errorf("%s:%d: cannot define a matcher outside of a site block: '%s'", k.File, k.Line, k.Text)
71				}
72				if _, ok := registeredDirectives[k.Text]; ok {
73					return nil, warnings, fmt.Errorf("%s:%d: parsed '%s' as a site address, but it is a known directive; directives must appear in a site block", k.File, k.Line, k.Text)
74				}
75			}
76			originalServerBlocks = append(originalServerBlocks, serverBlock{
77				block: sblock,
78				pile:  make(map[string][]ConfigValue),
79			})
80		}
81	
82		// apply any global options
83		var err error
84		originalServerBlocks, err = st.evaluateGlobalOptionsBlock(originalServerBlocks, options)
85		if err != nil {
86			return nil, warnings, err
87		}
88	
89		// Resolve the directive order for this adaptation. The "order" global
90		// option stores a per-adaptation order in options; we read it here once
91		// and thread it through every Helper and subroute build below. This keeps
92		// the ordering local to the call even when one Adapter is shared by
93		// concurrent adaptations.
94		adaptDirectiveOrder := directiveOrderForOptions(options)
95	
96		// this will replace both static and user-defined placeholder shorthands
97		// with actual identifiers used by Caddy
98		replacer := NewShorthandReplacer()
99	
100		originalServerBlocks, err = st.extractNamedRoutes(originalServerBlocks, options, &warnings, replacer, adaptDirectiveOrder)
101		if err != nil {
102			return nil, warnings, err
103		}
104	
105		for _, sb := range originalServerBlocks {
106			for i := range sb.block.Segments {
107				replacer.ApplyToSegment(&sb.block.Segments[i])
108			}
109	
110			if len(sb.block.Keys) == 0 {
111				return nil, warnings, fmt.Errorf("server block without any key is global configuration, and if used, it must be first")
112			}
113	
114			// extract matcher definitions
115			matcherDefs := make(map[string]caddy.ModuleMap)
116			for _, segment := range sb.block.Segments {
117				if dir := segment.Directive(); strings.HasPrefix(dir, matcherPrefix) {
118					d := caddyfile.NewDispenser(segment)
119					err := parseMatcherDefinitions(d, matcherDefs)
120					if err != nil {
121						return nil, warnings, err
122					}
123				}
124			}
125	
126			// evaluate each directive ("segment") in this block
127			for _, segment := range sb.block.Segments {
128				dir := segment.Directive()
129	
130				if strings.HasPrefix(dir, matcherPrefix) {
131					// matcher definitions were pre-processed
132					continue
133				}
134	
135				dirFunc, ok := registeredDirectives[dir]
136				if !ok {
137					tkn := segment[0]
138					message := "%s:%d: unrecognized directive: %s"
139					if !sb.block.HasBraces {
140						message += "\nDid you mean to define a second site? If so, you must use curly braces around each site to separate their configurations."
141					}
142					return nil, warnings, fmt.Errorf(message, tkn.File, tkn.Line, dir)
143				}
144	
145				h := Helper{
146					Dispenser:      caddyfile.NewDispenser(segment),
147					options:        options,
148					warnings:       &warnings,
149					matcherDefs:    matcherDefs,
150					parentBlock:    sb.block,
151					groupCounter:   gc,
152					State:          state,
153					BlockState:     state,
154					directiveOrder: adaptDirectiveOrder,
155				}
156	
157				results, err := dirFunc(h)
158				if err != nil {
159					return nil, warnings, fmt.Errorf("parsing caddyfile tokens for '%s': %v", dir, err)
160				}
161	
162				dir = normalizeDirectiveName(dir)
163	
164				for _, result := range results {
165					result.directive = dir
166					sb.pile[result.Class] = append(sb.pile[result.Class], result)
167				}
168	
169				// specially handle named routes that were pulled out from
170				// the invoke directive, which could be nested anywhere within
171				// some subroutes in this directive; we add them to the pile
172				// for this server block
173				if state[namedRouteKey] != nil {
174					for name := range state[namedRouteKey].(map[string]struct{}) {
175						result := ConfigValue{Class: namedRouteKey, Value: name}
176						sb.pile[result.Class] = append(sb.pile[result.Class], result)
177					}
178					state[namedRouteKey] = nil
179				}
180			}
181		}
182	
183		// map
184		sbmap, err := st.mapAddressToProtocolToServerBlocks(originalServerBlocks, options)
185		if err != nil {
186			return nil, warnings, err
187		}
188	
189		// reduce
190		pairings := st.consolidateAddrMappings(sbmap)
191	
192		// each pairing of listener addresses to list of server
193		// blocks is basically a server definition
194		servers, err := st.serversFromPairings(pairings, options, &warnings, gc, adaptDirectiveOrder)
195		if err != nil {
196			return nil, warnings, err
197		}
198	
199		// hoist the metrics config from per-server to global
200		metrics, _ := options["metrics"].(*caddyhttp.Metrics)
201		for _, s := range servers {
202			if s.Metrics != nil {
203				metrics = cmp.Or(metrics, &caddyhttp.Metrics{})
204				metrics = &caddyhttp.Metrics{
205					PerHost: metrics.PerHost || s.Metrics.PerHost,
206				}
207				s.Metrics = nil // we don't need it anymore
208			}
209		}
210	
211		// now that each server is configured, make the HTTP app
212		httpApp := caddyhttp.App{
213			HTTPPort:      tryInt(options["http_port"], &warnings),
214			HTTPSPort:     tryInt(options["https_port"], &warnings),
215			GracePeriod:   tryDuration(options["grace_period"], &warnings),
216			ShutdownDelay: tryDuration(options["shutdown_delay"], &warnings),
217			Metrics:       metrics,
218			Servers:       servers,
219		}
220	
221		// then make the TLS app
222		tlsApp, warnings, err := st.buildTLSApp(pairings, options, warnings)
223		if err != nil {
224			return nil, warnings, err
225		}
226	
227		// then make the PKI app
228		pkiApp, warnings, err := st.buildPKIApp(pairings, options, warnings)
229		if err != nil {
230			return nil, warnings, err
231		}
232	
233		// extract any custom logs, and enforce configured levels
234		var customLogs []namedCustomLog
235		var hasDefaultLog bool
236		addCustomLog := func(ncl namedCustomLog) {
237			if ncl.name == "" {
238				return
239			}
240			if ncl.name == caddy.DefaultLoggerName {
241				hasDefaultLog = true
242			}
243			if _, ok := options["debug"]; ok && ncl.log != nil && ncl.log.Level == "" {
244				ncl.log.Level = zap.DebugLevel.CapitalString()
245			}
246			customLogs = append(customLogs, ncl)
247		}
248	
249		// Apply global log options, when set
250		if options["log"] != nil {
251			for _, logValue := range options["log"].([]ConfigValue) {
252				addCustomLog(logValue.Value.(namedCustomLog))
253			}
254		}
255	
256		if !hasDefaultLog {
257			// if the default log was not customized, ensure we
258			// configure it with any applicable options
259			if _, ok := options["debug"]; ok {
260				customLogs = append(customLogs, namedCustomLog{
261					name: caddy.DefaultLoggerName,
262					log: &caddy.CustomLog{
263						BaseLog: caddy.BaseLog{Level: zap.DebugLevel.CapitalString()},
264					},
265				})
266			}
267		}
268	
269		// Apply server-specific log options
270		for _, p := range pairings {
271			for _, sb := range p.serverBlocks {
272				for _, clVal := range sb.pile["custom_log"] {
273					addCustomLog(clVal.Value.(namedCustomLog))
274				}
275			}
276		}
277	
278		// annnd the top-level config, then we're done!
279		cfg := &caddy.Config{AppsRaw: make(caddy.ModuleMap)}
280	
281		// loop through the configured options, and if any of
282		// them are an httpcaddyfile App, then we insert them
283		// into the config as raw Caddy apps
284		for _, opt := range options {
285			if app, ok := opt.(App); ok {
286				cfg.AppsRaw[app.Name] = app.Value
287			}
288		}
289	
290		// insert the standard Caddy apps into the config
291		if len(httpApp.Servers) > 0 {
292			cfg.AppsRaw["http"] = caddyconfig.JSON(httpApp, &warnings)
293		}
294		if !reflect.DeepEqual(tlsApp, &caddytls.TLS{CertificatesRaw: make(caddy.ModuleMap)}) {
295			cfg.AppsRaw["tls"] = caddyconfig.JSON(tlsApp, &warnings)
296		}
297		if !reflect.DeepEqual(pkiApp, &caddypki.PKI{CAs: make(map[string]*caddypki.CA)}) {
298			cfg.AppsRaw["pki"] = caddyconfig.JSON(pkiApp, &warnings)
299		}
300		if filesystems, ok := options["filesystem"].(caddy.Module); ok {
301			cfg.AppsRaw["caddy.filesystems"] = caddyconfig.JSON(
302				filesystems,
303				&warnings)
304		}
305	
306		if storageCvtr, ok := options["storage"].(caddy.StorageConverter); ok {
307			cfg.StorageRaw = caddyconfig.JSONModuleObject(storageCvtr,
308				"module",
309				storageCvtr.(caddy.Module).CaddyModule().ID.Name(),
310				&warnings)
311		}
312		if adminConfig, ok := options["admin"].(*caddy.AdminConfig); ok && adminConfig != nil {
313			cfg.Admin = adminConfig
314		}
315		if pc, ok := options["persist_config"].(string); ok && pc == "off" {
316			if cfg.Admin == nil {
317				cfg.Admin = new(caddy.AdminConfig)
318			}
319			if cfg.Admin.Config == nil {
320				cfg.Admin.Config = new(caddy.ConfigSettings)
321			}
322			cfg.Admin.Config.Persist = new(bool)
323		}
324	
325		if len(customLogs) > 0 {
326			if cfg.Logging == nil {
327				cfg.Logging = &caddy.Logging{
328					Logs: make(map[string]*caddy.CustomLog),
329				}
330			}
331	
332			// Add the default log first if defined, so that it doesn't
333			// accidentally get re-created below due to the Exclude logic
334			for _, ncl := range customLogs {
335				if ncl.name == caddy.DefaultLoggerName && ncl.log != nil {
336					cfg.Logging.Logs[caddy.DefaultLoggerName] = ncl.log
337					break
338				}
339			}
340	
341			// Add the rest of the custom logs
342			for _, ncl := range customLogs {
343				if ncl.log == nil || ncl.name == caddy.DefaultLoggerName {
344					continue
345				}
346				if ncl.name != "" {
347					cfg.Logging.Logs[ncl.name] = ncl.log
348				}
349				// most users seem to prefer not writing access logs
350				// to the default log when they are directed to a
351				// file or have any other special customization
352				if ncl.name != caddy.DefaultLoggerName && len(ncl.log.Include) > 0 {
353					defaultLog, ok := cfg.Logging.Logs[caddy.DefaultLoggerName]
354					if !ok {
355						defaultLog = new(caddy.CustomLog)
356						cfg.Logging.Logs[caddy.DefaultLoggerName] = defaultLog
357					}
358					defaultLog.Exclude = append(defaultLog.Exclude, ncl.log.Include...)
359	
360					// avoid duplicates by sorting + compacting
361					sort.Strings(defaultLog.Exclude)
362					defaultLog.Exclude = slices.Compact(defaultLog.Exclude)
363				}
364			}
365			// we may have not actually added anything, so remove if empty
366			if len(cfg.Logging.Logs) == 0 {
367				cfg.Logging = nil
368			}
369		}
370	
371		return cfg, warnings, nil
372	}
