374	// evaluateGlobalOptionsBlock evaluates the global options block,
375	// which is expected to be the first server block if it has zero
376	// keys. It returns the updated list of server blocks with the
377	// global options block removed, and updates options accordingly.
378	func (ServerType) evaluateGlobalOptionsBlock(serverBlocks []serverBlock, options map[string]any) ([]serverBlock, error) {
379		if len(serverBlocks) == 0 || len(serverBlocks[0].block.Keys) > 0 {
380			return serverBlocks, nil
381		}
382	
383		for _, segment := range serverBlocks[0].block.Segments {
384			opt := segment.Directive()
385			var val any
386			var err error
387			disp := caddyfile.NewDispenser(segment)
388	
389			optFunc, ok := registeredGlobalOptions[opt]
390			if !ok {
391				tkn := segment[0]
392				return nil, fmt.Errorf("%s:%d: unrecognized global option: %s", tkn.File, tkn.Line, opt)
393			}
394	
395			val, err = optFunc(disp, options[opt])
396			if err != nil {
397				return nil, fmt.Errorf("parsing caddyfile tokens for '%s': %v", opt, err)
398			}
399	
400			// As a special case, fold multiple "servers" options together
401			// in an array instead of overwriting a possible existing value
402			if opt == "servers" {
403				existingOpts, ok := options[opt].([]serverOptions)
404				if !ok {
405					existingOpts = []serverOptions{}
406				}
407				serverOpts, ok := val.(serverOptions)
408				if !ok {
409					return nil, fmt.Errorf("unexpected type from 'servers' global options: %T", val)
410				}
411				options[opt] = append(existingOpts, serverOpts)
412				continue
413			}
414			// Additionally, fold multiple "log" options together into an
415			// array so that multiple loggers can be configured.
416			if opt == "log" {
417				existingOpts, ok := options[opt].([]ConfigValue)
418				if !ok {
419					existingOpts = []ConfigValue{}
420				}
421				logOpts, ok := val.([]ConfigValue)
422				if !ok {
423					return nil, fmt.Errorf("unexpected type from 'log' global options: %T", val)
424				}
425				options[opt] = append(existingOpts, logOpts...)
426				continue
427			}
428			// Also fold multiple "default_bind" options together into an
429			// array so that server blocks can have multiple binds by default.
430			if opt == "default_bind" {
431				existingOpts, ok := options[opt].([]ConfigValue)
432				if !ok {
433					existingOpts = []ConfigValue{}
434				}
435				defaultBindOpts, ok := val.([]ConfigValue)
436				if !ok {
437					return nil, fmt.Errorf("unexpected type from 'default_bind' global options: %T", val)
438				}
439				options[opt] = append(existingOpts, defaultBindOpts...)
440				continue
441			}
442	
443			options[opt] = val
444		}
445	
446		// If we got "servers" options, we'll sort them by their listener address
447		if serverOpts, ok := options["servers"].([]serverOptions); ok {
448			sort.Slice(serverOpts, func(i, j int) bool {
449				return len(serverOpts[i].ListenerAddress) > len(serverOpts[j].ListenerAddress)
450			})
451	
452			// Reject the config if there are duplicate listener address
453			seen := make(map[string]bool)
454			for _, entry := range serverOpts {
455				if _, alreadySeen := seen[entry.ListenerAddress]; alreadySeen {
456					return nil, fmt.Errorf("cannot have 'servers' global options with duplicate listener addresses: %s", entry.ListenerAddress)
457				}
458				seen[entry.ListenerAddress] = true
459			}
460		}
461	
462		return serverBlocks[1:], nil
463	}
