465	// extractNamedRoutes pulls out any named route server blocks
466	// so they don't get parsed as sites, and stores them in options
467	// for later.
468	func (ServerType) extractNamedRoutes(
469		serverBlocks []serverBlock,
470		options map[string]any,
471		warnings *[]caddyconfig.Warning,
472		replacer ShorthandReplacer,
473		order []string,
474	) ([]serverBlock, error) {
475		namedRoutes := map[string]*caddyhttp.Route{}
476	
477		gc := counter{new(int)}
478		state := make(map[string]any)
479	
480		// copy the server blocks so we can
481		// splice out the named route ones
482		filtered := append([]serverBlock{}, serverBlocks...)
483		index := -1
484	
485		for _, sb := range serverBlocks {
486			index++
487			if !sb.block.IsNamedRoute {
488				continue
489			}
490	
491			// splice out this block, because we know it's not a real server
492			filtered = append(filtered[:index], filtered[index+1:]...)
493			index--
494	
495			if len(sb.block.Segments) == 0 {
496				continue
497			}
498	
499			wholeSegment := caddyfile.Segment{}
500			for i := range sb.block.Segments {
501				// replace user-defined placeholder shorthands in extracted named routes
502				replacer.ApplyToSegment(&sb.block.Segments[i])
503	
504				// zip up all the segments since ParseSegmentAsSubroute
505				// was designed to take a directive+
506				wholeSegment = append(wholeSegment, sb.block.Segments[i]...)
507			}
508	
509			h := Helper{
510				Dispenser:      caddyfile.NewDispenser(wholeSegment),
511				options:        options,
512				warnings:       warnings,
513				matcherDefs:    nil,
514				parentBlock:    sb.block,
515				groupCounter:   gc,
516				State:          state,
517				BlockState:     state,
518				directiveOrder: order,
519			}
520	
521			handler, err := ParseSegmentAsSubroute(h)
522			if err != nil {
523				return nil, err
524			}
525			subroute := handler.(*caddyhttp.Subroute)
526			route := caddyhttp.Route{}
527	
528			if len(subroute.Routes) == 1 && len(subroute.Routes[0].MatcherSetsRaw) == 0 {
529				// if there's only one route with no matcher, then we can simplify
530				route.HandlersRaw = append(route.HandlersRaw, subroute.Routes[0].HandlersRaw[0])
531			} else {
532				// otherwise we need the whole subroute
533				route.HandlersRaw = []json.RawMessage{caddyconfig.JSONModuleObject(handler, "handler", subroute.CaddyModule().ID.Name(), h.warnings)}
534			}
535	
536			namedRoutes[sb.block.GetKeysText()[0]] = &route
537		}
538		options["named_routes"] = namedRoutes
539	
540		return filtered, nil
541	}
