543	// serversFromPairings creates the servers for each pairing of addresses
544	// to server blocks. Each pairing is essentially a server definition.
545	func (st *ServerType) serversFromPairings(
546		pairings []sbAddrAssociation,
547		options map[string]any,
548		warnings *[]caddyconfig.Warning,
549		groupCounter counter,
550		order []string,
551	) (map[string]*caddyhttp.Server, error) {
552		servers := make(map[string]*caddyhttp.Server)
553		defaultSNI := tryString(options["default_sni"], warnings)
554		fallbackSNI := tryString(options["fallback_sni"], warnings)
555	
556		httpPort := strconv.Itoa(caddyhttp.DefaultHTTPPort)
557		if hp, ok := options["http_port"].(int); ok {
558			httpPort = strconv.Itoa(hp)
559		}
560		httpsPort := strconv.Itoa(caddyhttp.DefaultHTTPSPort)
561		if hsp, ok := options["https_port"].(int); ok {
562			httpsPort = strconv.Itoa(hsp)
563		}
564		autoHTTPS := []string{}
565		if ah, ok := options["auto_https"].([]string); ok {
566			autoHTTPS = ah
567		}
568	
569		for i, p := range pairings {
570			// detect ambiguous site definitions: server blocks which
571			// have the same host bound to the same interface (listener
572			// address), otherwise their routes will improperly be added
573			// to the same server (see issue #4635)
574			for j, sblock1 := range p.serverBlocks {
575				for _, key := range sblock1.block.GetKeysText() {
576					for k, sblock2 := range p.serverBlocks {
577						if k == j {
578							continue
579						}
580						if slices.Contains(sblock2.block.GetKeysText(), key) {
581							return nil, fmt.Errorf("ambiguous site definition: %s", key)
582						}
583					}
584				}
585			}
586	
587			var (
588				addresses []string
589				protocols [][]string
590			)
591	
592			for _, addressWithProtocols := range p.addressesWithProtocols {
593				addresses = append(addresses, addressWithProtocols.address)
594				protocols = append(protocols, addressWithProtocols.protocols)
595			}
596	
597			srv := &caddyhttp.Server{
598				Listen:          addresses,
599				ListenProtocols: protocols,
600			}
601	
602			// remove srv.ListenProtocols[j] if it only contains the default protocols
603			for j, lnProtocols := range srv.ListenProtocols {
604				srv.ListenProtocols[j] = nil
605				for _, lnProtocol := range lnProtocols {
606					if lnProtocol != "" {
607						srv.ListenProtocols[j] = lnProtocols
608						break
609					}
610				}
611			}
612	
613			// remove srv.ListenProtocols if it only contains the default protocols for all listen addresses
614			listenProtocols := srv.ListenProtocols
615			srv.ListenProtocols = nil
616			for _, lnProtocols := range listenProtocols {
617				if lnProtocols != nil {
618					srv.ListenProtocols = listenProtocols
619					break
620				}
621			}
622	
623			// handle the auto_https global option
624			for _, val := range autoHTTPS {
625				switch val {
626				case "off":
627					if srv.AutoHTTPS == nil {
628						srv.AutoHTTPS = new(caddyhttp.AutoHTTPSConfig)
629					}
630					srv.AutoHTTPS.Disabled = true
631	
632				case "disable_redirects":
633					if srv.AutoHTTPS == nil {
634						srv.AutoHTTPS = new(caddyhttp.AutoHTTPSConfig)
635					}
636					srv.AutoHTTPS.DisableRedir = true
637	
638				case "disable_certs":
639					if srv.AutoHTTPS == nil {
640						srv.AutoHTTPS = new(caddyhttp.AutoHTTPSConfig)
641					}
642					srv.AutoHTTPS.DisableCerts = true
643	
644				case "ignore_loaded_certs":
645					if srv.AutoHTTPS == nil {
646						srv.AutoHTTPS = new(caddyhttp.AutoHTTPSConfig)
647					}
648					srv.AutoHTTPS.IgnoreLoadedCerts = true
649				}
650			}
651	
652			// Using paths in site addresses is deprecated
653			// See ParseAddress() where parsing should later reject paths
654			// See https://github.com/caddyserver/caddy/pull/4728 for a full explanation
655			for _, sblock := range p.serverBlocks {
656				for _, addr := range sblock.parsedKeys {
657					if addr.Path != "" {
658						caddy.Log().Named("caddyfile").Warn("Using a path in a site address is deprecated; please use the 'handle' directive instead", zap.String("address", addr.String()))
659					}
660				}
661			}
662	
663			// sort server blocks by their keys; this is important because
664			// only the first matching site should be evaluated, and we should
665			// attempt to match most specific site first (host and path), in
666			// case their matchers overlap; we do this somewhat naively by
667			// descending sort by length of host then path
668			sort.SliceStable(p.serverBlocks, func(i, j int) bool {
669				// TODO: we could pre-process the specificities for efficiency,
670				// but I don't expect many blocks will have THAT many keys...
671				var iLongestPath, jLongestPath string
672				var iLongestHost, jLongestHost string
673				var iWildcardHost, jWildcardHost bool
674				for _, addr := range p.serverBlocks[i].parsedKeys {
675					if strings.Contains(addr.Host, "*") || addr.Host == "" {
676						iWildcardHost = true
677					}
678					if specificity(addr.Host) > specificity(iLongestHost) {
679						iLongestHost = addr.Host
680					}
681					if specificity(addr.Path) > specificity(iLongestPath) {
682						iLongestPath = addr.Path
683					}
684				}
685				for _, addr := range p.serverBlocks[j].parsedKeys {
686					if strings.Contains(addr.Host, "*") || addr.Host == "" {
687						jWildcardHost = true
688					}
689					if specificity(addr.Host) > specificity(jLongestHost) {
690						jLongestHost = addr.Host
691					}
692					if specificity(addr.Path) > specificity(jLongestPath) {
693						jLongestPath = addr.Path
694					}
695				}
696				// catch-all blocks (blocks with no hostname) should always go
697				// last, even after blocks with wildcard hosts
698				if specificity(iLongestHost) == 0 {
699					return false
700				}
701				if specificity(jLongestHost) == 0 {
702					return true
703				}
704				if iWildcardHost != jWildcardHost {
705					// site blocks that have a key with a wildcard in the hostname
706					// must always be less specific than blocks without one; see
707					// https://github.com/caddyserver/caddy/issues/3410
708					return jWildcardHost && !iWildcardHost
709				}
710				if specificity(iLongestHost) == specificity(jLongestHost) {
711					return len(iLongestPath) > len(jLongestPath)
712				}
713				return specificity(iLongestHost) > specificity(jLongestHost)
714			})
715	
716			var hasCatchAllTLSConnPolicy, addressQualifiesForTLS bool
717			autoHTTPSWillAddConnPolicy := srv.AutoHTTPS == nil || !srv.AutoHTTPS.Disabled
718	
719			// if needed, the ServerLogConfig is initialized beforehand so
720			// that all server blocks can populate it with data, even when not
721			// coming with a log directive
722			for _, sblock := range p.serverBlocks {
723				if len(sblock.pile["custom_log"]) != 0 {
724					srv.Logs = new(caddyhttp.ServerLogConfig)
725					break
726				}
727			}
728	
729			// add named routes to the server if 'invoke' was used inside of it
730			configuredNamedRoutes := options["named_routes"].(map[string]*caddyhttp.Route)
731			for _, sblock := range p.serverBlocks {
732				if len(sblock.pile[namedRouteKey]) == 0 {
733					continue
734				}
735				for _, value := range sblock.pile[namedRouteKey] {
736					if srv.NamedRoutes == nil {
737						srv.NamedRoutes = map[string]*caddyhttp.Route{}
738					}
739					name := value.Value.(string)
740					if configuredNamedRoutes[name] == nil {
741						return nil, fmt.Errorf("cannot invoke named route '%s', which was not defined", name)
742					}
743					srv.NamedRoutes[name] = configuredNamedRoutes[name]
744				}
745			}
746	
747			// create a subroute for each site in the server block
748			for _, sblock := range p.serverBlocks {
749				matcherSetsEnc, err := st.compileEncodedMatcherSets(sblock)
750				if err != nil {
751					return nil, fmt.Errorf("server block %v: compiling matcher sets: %v", sblock.block.Keys, err)
752				}
753	
754				hosts := sblock.hostsFromKeys(false)
755	
756				// emit warnings if user put unspecified IP addresses; they probably want the bind directive
757				for _, h := range hosts {
758					if h == "0.0.0.0" || h == "::" {
759						caddy.Log().Named("caddyfile").Warn("Site block has an unspecified IP address which only matches requests having that Host header; you probably want the 'bind' directive to configure the socket", zap.String("address", h))
760					}
761				}
762	
763				// collect hosts that are forced to be automated
764				forceAutomatedNames := make(map[string]struct{})
765				if _, ok := sblock.pile["tls.force_automate"]; ok {
766					for _, host := range hosts {
767						forceAutomatedNames[host] = struct{}{}
768					}
769				}
770	
771				// tls: connection policies
772				if cpVals, ok := sblock.pile["tls.connection_policy"]; ok {
773					// tls connection policies
774					for _, cpVal := range cpVals {
775						cp := cpVal.Value.(*caddytls.ConnectionPolicy)
776	
777						// make sure the policy covers all hostnames from the block
778						for _, h := range hosts {
779							if h == defaultSNI {
780								hosts = append(hosts, "")
781								cp.DefaultSNI = defaultSNI
782								break
783							}
784							if h == fallbackSNI {
785								hosts = append(hosts, "")
786								cp.FallbackSNI = fallbackSNI
787								break
788							}
789						}
790	
791						if len(hosts) > 0 {
792							slices.Sort(hosts) // for deterministic JSON output
793							cp.MatchersRaw = caddy.ModuleMap{
794								"sni": caddyconfig.JSON(hosts, warnings), // make sure to match all hosts, not just auto-HTTPS-qualified ones
795							}
796						} else {
797							cp.DefaultSNI = defaultSNI
798							cp.FallbackSNI = fallbackSNI
799						}
800	
801						// only append this policy if it actually changes something,
802						// or if the configuration explicitly automates certs for
803						// these names (this is necessary to hoist a connection policy
804						// above one that may manually load a wildcard cert that would
805						// otherwise clobber the automated one; the code that appends
806						// policies that manually load certs comes later, so they're
807						// lower in the list)
808						if !cp.SettingsEmpty() || mapContains(forceAutomatedNames, hosts) {
809							srv.TLSConnPolicies = append(srv.TLSConnPolicies, cp)
810							hasCatchAllTLSConnPolicy = len(hosts) == 0
811						}
812					}
813				}
814	
815				for _, addr := range sblock.parsedKeys {
816					// if server only uses HTTP port, auto-HTTPS will not apply
817					if listenersUseAnyPortOtherThan(srv.Listen, httpPort) {
818						// exclude any hosts that were defined explicitly with "http://"
819						// in the key from automated cert management (issue #2998)
820						if addr.Scheme == "http" && addr.Host != "" {
821							if srv.AutoHTTPS == nil {
822								srv.AutoHTTPS = new(caddyhttp.AutoHTTPSConfig)
823							}
824							if !slices.Contains(srv.AutoHTTPS.Skip, addr.Host) {
825								srv.AutoHTTPS.Skip = append(srv.AutoHTTPS.Skip, addr.Host)
826							}
827						}
828					}
829	
830					// If TLS is specified as directive, it will also result in 1 or more connection policy being created
831					// Thus, catch-all address with non-standard port, e.g. :8443, can have TLS enabled without
832					// specifying prefix "https://"
833					// Second part of the condition is to allow creating TLS conn policy even though `auto_https` has been disabled
834					// ensuring compatibility with behavior described in below link
835					// https://caddy.community/t/making-sense-of-auto-https-and-why-disabling-it-still-serves-https-instead-of-http/9761
836					createdTLSConnPolicies, ok := sblock.pile["tls.connection_policy"]
837					hasTLSEnabled := (ok && len(createdTLSConnPolicies) > 0) ||
838						(addr.Host != "" && (srv.AutoHTTPS == nil || !slices.Contains(srv.AutoHTTPS.Skip, addr.Host)))
839	
840					// we'll need to remember if the address qualifies for auto-HTTPS, so we
841					// can add a TLS conn policy if necessary
842					if addr.Scheme == "https" ||
843						(addr.Scheme != "http" && addr.Port != httpPort && hasTLSEnabled) {
844						addressQualifiesForTLS = true
845					}
846	
847					// predict whether auto-HTTPS will add the conn policy for us; if so, we
848					// may not need to add one for this server
849					autoHTTPSWillAddConnPolicy = autoHTTPSWillAddConnPolicy &&
850						(addr.Port == httpsPort || (addr.Port != httpPort && addr.Host != ""))
851				}
852	
853				// Look for any config values that provide listener wrappers on the server block
854				for _, listenerConfig := range sblock.pile["listener_wrapper"] {
855					listenerWrapper, ok := listenerConfig.Value.(caddy.ListenerWrapper)
856					if !ok {
857						return nil, fmt.Errorf("config for a listener wrapper did not provide a value that implements caddy.ListenerWrapper")
858					}
859					jsonListenerWrapper := caddyconfig.JSONModuleObject(
860						listenerWrapper,
861						"wrapper",
862						listenerWrapper.(caddy.Module).CaddyModule().ID.Name(),
863						warnings)
864					srv.ListenerWrappersRaw = append(srv.ListenerWrappersRaw, jsonListenerWrapper)
865				}
866	
867				// Look for any config values that provide packet conn wrappers on the server block
868				for _, listenerConfig := range sblock.pile["packet_conn_wrapper"] {
869					packetConnWrapper, ok := listenerConfig.Value.(caddy.PacketConnWrapper)
870					if !ok {
871						return nil, fmt.Errorf("config for a packet conn wrapper did not provide a value that implements caddy.PacketConnWrapper")
872					}
873					jsonPacketConnWrapper := caddyconfig.JSONModuleObject(
874						packetConnWrapper,
875						"wrapper",
876						packetConnWrapper.(caddy.Module).CaddyModule().ID.Name(),
877						warnings)
878					srv.PacketConnWrappersRaw = append(srv.PacketConnWrappersRaw, jsonPacketConnWrapper)
879				}
880	
881				// set up each handler directive, making sure to honor directive order
882				dirRoutes := sblock.pile["route"]
883				siteSubroute, err := buildSubroute(dirRoutes, groupCounter, true, order)
884				if err != nil {
885					return nil, err
886				}
887	
888				// add the site block's route(s) to the server
889				srv.Routes = appendSubrouteToRouteList(srv.Routes, siteSubroute, matcherSetsEnc, p, warnings)
890	
891				// if error routes are defined, add those too
892				if errorSubrouteVals, ok := sblock.pile["error_route"]; ok {
893					if srv.Errors == nil {
894						srv.Errors = new(caddyhttp.HTTPErrorConfig)
895					}
896					sort.SliceStable(errorSubrouteVals, func(i, j int) bool {
897						sri, srj := errorSubrouteVals[i].Value.(*caddyhttp.Subroute), errorSubrouteVals[j].Value.(*caddyhttp.Subroute)
898						if len(sri.Routes[0].MatcherSetsRaw) == 0 && len(srj.Routes[0].MatcherSetsRaw) != 0 {
899							return false
900						}
901						return true
902					})
903					errorsSubroute := &caddyhttp.Subroute{}
904					for _, val := range errorSubrouteVals {
905						sr := val.Value.(*caddyhttp.Subroute)
906						errorsSubroute.Routes = append(errorsSubroute.Routes, sr.Routes...)
907					}
908					srv.Errors.Routes = appendSubrouteToRouteList(srv.Errors.Routes, errorsSubroute, matcherSetsEnc, p, warnings)
909				}
910	
911				// add log associations
912				// see https://github.com/caddyserver/caddy/issues/3310
913				sblockLogHosts := sblock.hostsFromKeys(true)
914				for _, cval := range sblock.pile["custom_log"] {
915					ncl := cval.Value.(namedCustomLog)
916	
917					// if `no_hostname` is set, then this logger will not
918					// be associated with any of the site block's hostnames,
919					// and only be usable via the `log_name` directive
920					// or the `access_logger_names` variable
921					if ncl.noHostname {
922						continue
923					}
924	
925					if sblock.hasHostCatchAllKey() && len(ncl.hostnames) == 0 {
926						// all requests for hosts not able to be listed should use
927						// this log because it's a catch-all-hosts server block
928						srv.Logs.DefaultLoggerName = ncl.name
929					} else if len(ncl.hostnames) > 0 {
930						// if the logger overrides the hostnames, map that to the logger name
931						for _, h := range ncl.hostnames {
932							if srv.Logs.LoggerNames == nil {
933								srv.Logs.LoggerNames = make(map[string]caddyhttp.StringArray)
934							}
935							srv.Logs.LoggerNames[h] = append(srv.Logs.LoggerNames[h], ncl.name)
936						}
937					} else {
938						// otherwise, map each host to the logger name
939						for _, h := range sblockLogHosts {
940							// strip the port from the host, if any
941							host, _, err := net.SplitHostPort(h)
942							if err != nil {
943								host = h
944							}
945							if srv.Logs.LoggerNames == nil {
946								srv.Logs.LoggerNames = make(map[string]caddyhttp.StringArray)
947							}
948							srv.Logs.LoggerNames[host] = append(srv.Logs.LoggerNames[host], ncl.name)
949						}
950					}
951				}
952				if srv.Logs != nil && len(sblock.pile["custom_log"]) == 0 {
953					// server has access logs enabled, but this server block does not
954					// enable access logs; therefore, all hosts of this server block
955					// should not be access-logged
956					if len(hosts) == 0 {
957						// if the server block has a catch-all-hosts key, then we should
958						// not log reqs to any host unless it appears in the map
959						srv.Logs.SkipUnmappedHosts = true
960					}
961					srv.Logs.SkipHosts = append(srv.Logs.SkipHosts, sblockLogHosts...)
962				}
963			}
964	
965			// sort for deterministic JSON output
966			if srv.Logs != nil {
967				slices.Sort(srv.Logs.SkipHosts)
968			}
969	
970			// a server cannot (natively) serve both HTTP and HTTPS at the
971			// same time, so make sure the configuration isn't in conflict
972			err := detectConflictingSchemes(srv, p.serverBlocks, options)
973			if err != nil {
974				return nil, err
975			}
976	
977			// a catch-all TLS conn policy is necessary to ensure TLS can
978			// be offered to all hostnames of the server; even though only
979			// one policy is needed to enable TLS for the server, that
980			// policy might apply to only certain TLS handshakes; but when
981			// using the Caddyfile, user would expect all handshakes to at
982			// least have a matching connection policy, so here we append a
983			// catch-all/default policy if there isn't one already (it's
984			// important that it goes at the end) - see issue #3004:
985			// https://github.com/caddyserver/caddy/issues/3004
986			// TODO: maybe a smarter way to handle this might be to just make the
987			// auto-HTTPS logic at provision-time detect if there is any connection
988			// policy missing for any HTTPS-enabled hosts, if so, add it... maybe?
989			if addressQualifiesForTLS &&
990				!hasCatchAllTLSConnPolicy &&
991				(len(srv.TLSConnPolicies) > 0 || !autoHTTPSWillAddConnPolicy || defaultSNI != "" || fallbackSNI != "") {
992				srv.TLSConnPolicies = append(srv.TLSConnPolicies, &caddytls.ConnectionPolicy{
993					DefaultSNI:  defaultSNI,
994					FallbackSNI: fallbackSNI,
995				})
996			}
997	
998			// tidy things up a bit
999			srv.TLSConnPolicies, err = consolidateConnPolicies(srv.TLSConnPolicies)
1000			if err != nil {
1001				return nil, fmt.Errorf("consolidating TLS connection policies for server %d: %v", i, err)
1002			}
1003			srv.Routes = consolidateRoutes(srv.Routes)
1004	
1005			servers[fmt.Sprintf("srv%d", i)] = srv
1006		}
1007	
1008		if err := applyServerOptions(servers, options, warnings); err != nil {
1009			return nil, fmt.Errorf("applying global server options: %v", err)
1010		}
1011	
1012		return servers, nil
1013	}
1014	
1015	func detectConflictingSchemes(srv *caddyhttp.Server, serverBlocks []serverBlock, options map[string]any) error {
1016		httpPort := strconv.Itoa(caddyhttp.DefaultHTTPPort)
1017		if hp, ok := options["http_port"].(int); ok {
1018			httpPort = strconv.Itoa(hp)
1019		}
1020		httpsPort := strconv.Itoa(caddyhttp.DefaultHTTPSPort)
1021		if hsp, ok := options["https_port"].(int); ok {
1022			httpsPort = strconv.Itoa(hsp)
1023		}
1024	
1025		var httpOrHTTPS string
1026		checkAndSetHTTP := func(addr Address) error {
1027			if httpOrHTTPS == "HTTPS" {
1028				errMsg := fmt.Errorf("server listening on %v is configured for HTTPS and cannot natively multiplex HTTP and HTTPS: %s",
1029					srv.Listen, addr.Original)
1030				if addr.Scheme == "" && addr.Host == "" {
1031					errMsg = fmt.Errorf("%s (try specifying https:// in the address)", errMsg)
1032				}
1033				return errMsg
1034			}
1035			if len(srv.TLSConnPolicies) > 0 {
1036				// any connection policies created for an HTTP server
1037				// is a logical conflict, as it would enable HTTPS
1038				return fmt.Errorf("server listening on %v is HTTP, but attempts to configure TLS connection policies", srv.Listen)
1039			}
1040			httpOrHTTPS = "HTTP"
1041			return nil
1042		}
1043		checkAndSetHTTPS := func(addr Address) error {
1044			if httpOrHTTPS == "HTTP" {
1045				return fmt.Errorf("server listening on %v is configured for HTTP and cannot natively multiplex HTTP and HTTPS: %s",
1046					srv.Listen, addr.Original)
1047			}
1048			httpOrHTTPS = "HTTPS"
1049			return nil
1050		}
1051	
1052		for _, sblock := range serverBlocks {
1053			for _, addr := range sblock.parsedKeys {
1054				if addr.Scheme == "http" || addr.Port == httpPort {
1055					if err := checkAndSetHTTP(addr); err != nil {
1056						return err
1057					}
1058				} else if addr.Scheme == "https" || addr.Port == httpsPort || len(srv.TLSConnPolicies) > 0 {
1059					if err := checkAndSetHTTPS(addr); err != nil {
1060						return err
1061					}
1062				} else if addr.Host == "" {
1063					if err := checkAndSetHTTP(addr); err != nil {
1064						return err
1065					}
1066				}
1067			}
1068		}
1069	
1070		return nil
1071	}
1072	
1073	// consolidateConnPolicies sorts any catch-all policy to the end, removes empty TLS connection
1074	// policies, and combines equivalent ones for a cleaner overall output.
1075	func consolidateConnPolicies(cps caddytls.ConnectionPolicies) (caddytls.ConnectionPolicies, error) {
1076		// catch-all policies (those without any matcher) should be at the
1077		// end, otherwise it nullifies any more specific policies
1078		sort.SliceStable(cps, func(i, j int) bool {
1079			return cps[j].MatchersRaw == nil && cps[i].MatchersRaw != nil
1080		})
1081	
1082		for i := 0; i < len(cps); i++ {
1083			// compare it to the others
1084			for j := 0; j < len(cps); j++ {
1085				if j == i {
1086					continue
1087				}
1088	
1089				// if they're exactly equal in every way, just keep one of them
1090				if reflect.DeepEqual(cps[i], cps[j]) {
1091					cps = slices.Delete(cps, j, j+1)
1092					i--
1093					break
1094				}
1095	
1096				// as a special case, if there are adjacent TLS conn policies that are identical except
1097				// by their matchers, and the matchers are specifically just ServerName ("sni") matchers
1098				// (by far the most common), we can combine them into a single policy
1099				if i == j-1 && len(cps[i].MatchersRaw) == 1 && len(cps[j].MatchersRaw) == 1 {
1100					if iSNIMatcherJSON, ok := cps[i].MatchersRaw["sni"]; ok {
1101						if jSNIMatcherJSON, ok := cps[j].MatchersRaw["sni"]; ok {
1102							// position of policies and the matcher criteria check out; if settings are
1103							// the same, then we can combine the policies; we have to unmarshal and
1104							// remarshal the matchers though
1105							if cps[i].SettingsEqual(*cps[j]) {
1106								var iSNIMatcher caddytls.MatchServerName
1107								if err := json.Unmarshal(iSNIMatcherJSON, &iSNIMatcher); err == nil {
1108									var jSNIMatcher caddytls.MatchServerName
1109									if err := json.Unmarshal(jSNIMatcherJSON, &jSNIMatcher); err == nil {
1110										iSNIMatcher = append(iSNIMatcher, jSNIMatcher...)
1111										cps[i].MatchersRaw["sni"], err = json.Marshal(iSNIMatcher)
1112										if err != nil {
1113											return nil, fmt.Errorf("recombining SNI matchers: %v", err)
1114										}
1115										cps = slices.Delete(cps, j, j+1)
1116										i--
1117										break
1118									}
1119								}
1120							}
1121						}
1122					}
1123				}
1124	
1125				// if they have the same matcher, try to reconcile each field: either they must
1126				// be identical, or we have to be able to combine them safely
1127				if reflect.DeepEqual(cps[i].MatchersRaw, cps[j].MatchersRaw) {
1128					if len(cps[i].ALPN) > 0 &&
1129						len(cps[j].ALPN) > 0 &&
1130						!reflect.DeepEqual(cps[i].ALPN, cps[j].ALPN) {
1131						return nil, fmt.Errorf("two policies with same match criteria have conflicting ALPN: %v vs. %v",
1132							cps[i].ALPN, cps[j].ALPN)
1133					}
1134					if len(cps[i].CipherSuites) > 0 &&
1135						len(cps[j].CipherSuites) > 0 &&
1136						!reflect.DeepEqual(cps[i].CipherSuites, cps[j].CipherSuites) {
1137						return nil, fmt.Errorf("two policies with same match criteria have conflicting cipher suites: %v vs. %v",
1138							cps[i].CipherSuites, cps[j].CipherSuites)
1139					}
1140					if cps[i].ClientAuthentication == nil &&
1141						cps[j].ClientAuthentication != nil &&
1142						!reflect.DeepEqual(cps[i].ClientAuthentication, cps[j].ClientAuthentication) {
1143						return nil, fmt.Errorf("two policies with same match criteria have conflicting client auth configuration: %+v vs. %+v",
1144							cps[i].ClientAuthentication, cps[j].ClientAuthentication)
1145					}
1146					if len(cps[i].Curves) > 0 &&
1147						len(cps[j].Curves) > 0 &&
1148						!reflect.DeepEqual(cps[i].Curves, cps[j].Curves) {
1149						return nil, fmt.Errorf("two policies with same match criteria have conflicting curves: %v vs. %v",
1150							cps[i].Curves, cps[j].Curves)
1151					}
1152					if cps[i].DefaultSNI != "" &&
1153						cps[j].DefaultSNI != "" &&
1154						cps[i].DefaultSNI != cps[j].DefaultSNI {
1155						return nil, fmt.Errorf("two policies with same match criteria have conflicting default SNI: %s vs. %s",
1156							cps[i].DefaultSNI, cps[j].DefaultSNI)
1157					}
1158					if cps[i].FallbackSNI != "" &&
1159						cps[j].FallbackSNI != "" &&
1160						cps[i].FallbackSNI != cps[j].FallbackSNI {
1161						return nil, fmt.Errorf("two policies with same match criteria have conflicting fallback SNI: %s vs. %s",
1162							cps[i].FallbackSNI, cps[j].FallbackSNI)
1163					}
1164					if cps[i].ProtocolMin != "" &&
1165						cps[j].ProtocolMin != "" &&
1166						cps[i].ProtocolMin != cps[j].ProtocolMin {
1167						return nil, fmt.Errorf("two policies with same match criteria have conflicting min protocol: %s vs. %s",
1168							cps[i].ProtocolMin, cps[j].ProtocolMin)
1169					}
1170					if cps[i].ProtocolMax != "" &&
1171						cps[j].ProtocolMax != "" &&
1172						cps[i].ProtocolMax != cps[j].ProtocolMax {
1173						return nil, fmt.Errorf("two policies with same match criteria have conflicting max protocol: %s vs. %s",
1174							cps[i].ProtocolMax, cps[j].ProtocolMax)
1175					}
1176					if cps[i].CertSelection != nil && cps[j].CertSelection != nil {
1177						// merging fields other than AnyTag is not implemented
1178						if !reflect.DeepEqual(cps[i].CertSelection.SerialNumber, cps[j].CertSelection.SerialNumber) ||
1179							!reflect.DeepEqual(cps[i].CertSelection.SubjectOrganization, cps[j].CertSelection.SubjectOrganization) ||
1180							cps[i].CertSelection.PublicKeyAlgorithm != cps[j].CertSelection.PublicKeyAlgorithm ||
1181							!reflect.DeepEqual(cps[i].CertSelection.AllTags, cps[j].CertSelection.AllTags) {
1182							return nil, fmt.Errorf("two policies with same match criteria have conflicting cert selections: %+v vs. %+v",
1183								cps[i].CertSelection, cps[j].CertSelection)
1184						}
1185					}
1186	
1187					// by now we've decided that we can merge the two -- we'll keep i and drop j
1188	
1189					if len(cps[i].ALPN) == 0 && len(cps[j].ALPN) > 0 {
1190						cps[i].ALPN = cps[j].ALPN
1191					}
1192					if len(cps[i].CipherSuites) == 0 && len(cps[j].CipherSuites) > 0 {
1193						cps[i].CipherSuites = cps[j].CipherSuites
1194					}
1195					if cps[i].ClientAuthentication == nil && cps[j].ClientAuthentication != nil {
1196						cps[i].ClientAuthentication = cps[j].ClientAuthentication
1197					}
1198					if len(cps[i].Curves) == 0 && len(cps[j].Curves) > 0 {
1199						cps[i].Curves = cps[j].Curves
1200					}
1201					if cps[i].DefaultSNI == "" && cps[j].DefaultSNI != "" {
1202						cps[i].DefaultSNI = cps[j].DefaultSNI
1203					}
1204					if cps[i].FallbackSNI == "" && cps[j].FallbackSNI != "" {
1205						cps[i].FallbackSNI = cps[j].FallbackSNI
1206					}
1207					if cps[i].ProtocolMin == "" && cps[j].ProtocolMin != "" {
1208						cps[i].ProtocolMin = cps[j].ProtocolMin
1209					}
1210					if cps[i].ProtocolMax == "" && cps[j].ProtocolMax != "" {
1211						cps[i].ProtocolMax = cps[j].ProtocolMax
1212					}
1213	
1214					if cps[i].CertSelection == nil && cps[j].CertSelection != nil {
1215						// if j is the only one with a policy, move it over to i
1216						cps[i].CertSelection = cps[j].CertSelection
1217					} else if cps[i].CertSelection != nil && cps[j].CertSelection != nil {
1218						// if both have one, then combine AnyTag
1219						for _, tag := range cps[j].CertSelection.AnyTag {
1220							if !slices.Contains(cps[i].CertSelection.AnyTag, tag) {
1221								cps[i].CertSelection.AnyTag = append(cps[i].CertSelection.AnyTag, tag)
1222							}
1223						}
1224					}
1225	
1226					cps = slices.Delete(cps, j, j+1)
1227					i--
1228					break
1229				}
1230			}
1231		}
1232	
1233		return cps, nil
1234	}
