1236	// appendSubrouteToRouteList appends the routes in subroute
1237	// to the routeList, optionally qualified by matchers.
1238	func appendSubrouteToRouteList(routeList caddyhttp.RouteList,
1239		subroute *caddyhttp.Subroute,
1240		matcherSetsEnc []caddy.ModuleMap,
1241		p sbAddrAssociation,
1242		warnings *[]caddyconfig.Warning,
1243	) caddyhttp.RouteList {
1244		// nothing to do if... there's nothing to do
1245		if len(matcherSetsEnc) == 0 && len(subroute.Routes) == 0 && subroute.Errors == nil {
1246			return routeList
1247		}
1248	
1249		// No need to wrap the handlers in a subroute if this is the only server block
1250		// and there is no matcher for it (doing so would produce unnecessarily nested
1251		// JSON), *unless* there is a host matcher within this site block; if so, then
1252		// we still need to wrap in a subroute because otherwise the host matcher from
1253		// the inside of the site block would be a top-level host matcher, which is
1254		// subject to auto-HTTPS (cert management), and using a host matcher within
1255		// a site block is a valid, common pattern for excluding domains from cert
1256		// management, leading to unexpected behavior; see issue #5124.
1257		wrapInSubroute := true
1258		if len(matcherSetsEnc) == 0 && len(p.serverBlocks) == 1 {
1259			var hasHostMatcher bool
1260		outer:
1261			for _, route := range subroute.Routes {
1262				for _, ms := range route.MatcherSetsRaw {
1263					for matcherName := range ms {
1264						if matcherName == "host" {
1265							hasHostMatcher = true
1266							break outer
1267						}
1268					}
1269				}
1270			}
1271			wrapInSubroute = hasHostMatcher
1272		}
1273	
1274		if wrapInSubroute {
1275			route := caddyhttp.Route{
1276				// the semantics of a site block in the Caddyfile dictate
1277				// that only the first matching one is evaluated, since
1278				// site blocks do not cascade nor inherit
1279				Terminal: true,
1280			}
1281			if len(matcherSetsEnc) > 0 {
1282				route.MatcherSetsRaw = matcherSetsEnc
1283			}
1284			if len(subroute.Routes) > 0 || subroute.Errors != nil {
1285				route.HandlersRaw = []json.RawMessage{
1286					caddyconfig.JSONModuleObject(subroute, "handler", "subroute", warnings),
1287				}
1288			}
1289			if len(route.MatcherSetsRaw) > 0 || len(route.HandlersRaw) > 0 {
1290				routeList = append(routeList, route)
1291			}
1292		} else {
1293			routeList = append(routeList, subroute.Routes...)
1294		}
1295	
1296		return routeList
1297	}
