1299	// buildSubroute turns the config values, which are expected to be routes
1300	// into a clean and orderly subroute that has all the routes within it.
1301	// order is the directive ordering in effect for the current adaptation.
1302	func buildSubroute(routes []ConfigValue, groupCounter counter, needsSorting bool, order []string) (*caddyhttp.Subroute, error) {
1303		if needsSorting {
1304			for _, val := range routes {
1305				if !slices.Contains(order, val.directive) {
1306					return nil, fmt.Errorf("directive '%s' is not an ordered HTTP handler, so it cannot be used here - try placing within a route block or using the order global option", val.directive)
1307				}
1308			}
1309	
1310			sortRoutes(routes, order)
1311		}
1312	
1313		subroute := new(caddyhttp.Subroute)
1314	
1315		// some directives are mutually exclusive (only first matching
1316		// instance should be evaluated); this is done by putting their
1317		// routes in the same group
1318		mutuallyExclusiveDirs := map[string]*struct {
1319			count     int
1320			groupName string
1321		}{
1322			// as a special case, group rewrite directives so that they are mutually exclusive;
1323			// this means that only the first matching rewrite will be evaluated, and that's
1324			// probably a good thing, since there should never be a need to do more than one
1325			// rewrite (I think?), and cascading rewrites smell bad... imagine these rewrites:
1326			//     rewrite /docs/json/* /docs/json/index.html
1327			//     rewrite /docs/*      /docs/index.html
1328			// (We use this on the Caddy website, or at least we did once.) The first rewrite's
1329			// result is also matched by the second rewrite, making the first rewrite pointless.
1330			// See issue #2959.
1331			"rewrite": {},
1332	
1333			// handle blocks are also mutually exclusive by definition
1334			"handle": {},
1335	
1336			// root just sets a variable, so if it was not mutually exclusive, intersecting
1337			// root directives would overwrite previously-matched ones; they should not cascade
1338			"root": {},
1339		}
1340	
1341		// we need to deterministically loop over each of these directives
1342		// in order to keep the group numbers consistent
1343		keys := make([]string, 0, len(mutuallyExclusiveDirs))
1344		for k := range mutuallyExclusiveDirs {
1345			keys = append(keys, k)
1346		}
1347		sort.Strings(keys)
1348	
1349		for _, meDir := range keys {
1350			info := mutuallyExclusiveDirs[meDir]
1351	
1352			// see how many instances of the directive there are
1353			for _, r := range routes {
1354				if r.directive == meDir {
1355					info.count++
1356					if info.count > 1 {
1357						break
1358					}
1359				}
1360			}
1361			// if there is more than one, put them in a group
1362			// (special case: "rewrite" directive must always be in
1363			// its own group--even if there is only one--because we
1364			// do not want a rewrite to be consolidated into other
1365			// adjacent routes that happen to have the same matcher,
1366			// see caddyserver/caddy#3108 - because the implied
1367			// intent of rewrite is to do an internal redirect,
1368			// we can't assume that the request will continue to
1369			// match the same matcher; anyway, giving a route a
1370			// unique group name should keep it from consolidating)
1371			if info.count > 1 || meDir == "rewrite" {
1372				info.groupName = groupCounter.nextGroup()
1373			}
1374		}
1375	
1376		// add all the routes piled in from directives
1377		for _, r := range routes {
1378			// put this route into a group if it is mutually exclusive
1379			if info, ok := mutuallyExclusiveDirs[r.directive]; ok {
1380				route := r.Value.(caddyhttp.Route)
1381				route.Group = info.groupName
1382				r.Value = route
1383			}
1384	
1385			switch route := r.Value.(type) {
1386			case caddyhttp.Subroute:
1387				// if a route-class config value is actually a Subroute handler
1388				// with nothing but a list of routes, then it is the intention
1389				// of the directive to keep these handlers together and in this
1390				// same order, but not necessarily in a subroute (if it wanted
1391				// to keep them in a subroute, the directive would have returned
1392				// a route with a Subroute as its handler); this is useful to
1393				// keep multiple handlers/routes together and in the same order
1394				// so that the sorting procedure we did above doesn't reorder them
1395				if route.Errors != nil {
1396					// if error handlers are also set, this is confusing; it's
1397					// probably supposed to be wrapped in a Route and encoded
1398					// as a regular handler route... programmer error.
1399					panic("found subroute with more than just routes; perhaps it should have been wrapped in a route?")
1400				}
1401				subroute.Routes = append(subroute.Routes, route.Routes...)
1402			case caddyhttp.Route:
1403				subroute.Routes = append(subroute.Routes, route)
1404			}
1405		}
1406	
1407		subroute.Routes = consolidateRoutes(subroute.Routes)
1408	
1409		return subroute, nil
1410	}
