1412	// normalizeDirectiveName ensures directives that should be sorted
1413	// at the same level are named the same before sorting happens.
1414	func normalizeDirectiveName(directive string) string {
1415		// As a special case, we want "handle_path" to be sorted
1416		// at the same level as "handle", so we force them to use
1417		// the same directive name after their parsing is complete.
1418		// See https://github.com/caddyserver/caddy/issues/3675#issuecomment-678042377
1419		if directive == "handle_path" {
1420			directive = "handle"
1421		}
1422		return directive
1423	}
1424	
1425	// consolidateRoutes combines routes with the same properties
1426	// (same matchers, same Terminal and Group settings) for a
1427	// cleaner overall output.
1428	func consolidateRoutes(routes caddyhttp.RouteList) caddyhttp.RouteList {
1429		for i := 0; i < len(routes)-1; i++ {
1430			if reflect.DeepEqual(routes[i].MatcherSetsRaw, routes[i+1].MatcherSetsRaw) &&
1431				routes[i].Terminal == routes[i+1].Terminal &&
1432				routes[i].Group == routes[i+1].Group {
1433				// keep the handlers in the same order, then splice out repetitive route
1434				routes[i].HandlersRaw = append(routes[i].HandlersRaw, routes[i+1].HandlersRaw...)
1435				routes = append(routes[:i+1], routes[i+2:]...)
1436				i--
1437			}
1438		}
1439		return routes
1440	}
