1442	func matcherSetFromMatcherToken(
1443		tkn caddyfile.Token,
1444		matcherDefs map[string]caddy.ModuleMap,
1445		warnings *[]caddyconfig.Warning,
1446	) (caddy.ModuleMap, bool, error) {
1447		// matcher tokens can be wildcards, simple path matchers,
1448		// or refer to a pre-defined matcher by some name
1449		if tkn.Text == "*" {
1450			// match all requests == no matchers, so nothing to do
1451			return nil, true, nil
1452		}
1453	
1454		// convenient way to specify a single path match
1455		if strings.HasPrefix(tkn.Text, "/") {
1456			return caddy.ModuleMap{
1457				"path": caddyconfig.JSON(caddyhttp.MatchPath{tkn.Text}, warnings),
1458			}, true, nil
1459		}
1460	
1461		// pre-defined matcher
1462		if strings.HasPrefix(tkn.Text, matcherPrefix) {
1463			m, ok := matcherDefs[tkn.Text]
1464			if !ok {
1465				return nil, false, fmt.Errorf("unrecognized matcher name: %+v", tkn.Text)
1466			}
1467			return m, true, nil
1468		}
1469	
1470		return nil, false, nil
1471	}
