1473	func (st *ServerType) compileEncodedMatcherSets(sblock serverBlock) ([]caddy.ModuleMap, error) {
1474		type hostPathPair struct {
1475			hostm caddyhttp.MatchHost
1476			pathm caddyhttp.MatchPath
1477		}
1478	
1479		// keep routes with common host and path matchers together
1480		var matcherPairs []*hostPathPair
1481	
1482		var catchAllHosts bool
1483		for _, addr := range sblock.parsedKeys {
1484			// choose a matcher pair that should be shared by this
1485			// server block; if none exists yet, create one
1486			var chosenMatcherPair *hostPathPair
1487			for _, mp := range matcherPairs {
1488				if (len(mp.pathm) == 0 && addr.Path == "") ||
1489					(len(mp.pathm) == 1 && mp.pathm[0] == addr.Path) {
1490					chosenMatcherPair = mp
1491					break
1492				}
1493			}
1494			if chosenMatcherPair == nil {
1495				chosenMatcherPair = new(hostPathPair)
1496				if addr.Path != "" {
1497					chosenMatcherPair.pathm = []string{addr.Path}
1498				}
1499				matcherPairs = append(matcherPairs, chosenMatcherPair)
1500			}
1501	
1502			// if one of the keys has no host (i.e. is a catch-all for
1503			// any hostname), then we need to null out the host matcher
1504			// entirely so that it matches all hosts
1505			if addr.Host == "" && !catchAllHosts {
1506				chosenMatcherPair.hostm = nil
1507				catchAllHosts = true
1508			}
1509			if catchAllHosts {
1510				continue
1511			}
1512	
1513			// add this server block's keys to the matcher
1514			// pair if it doesn't already exist
1515			if addr.Host != "" && !slices.Contains(chosenMatcherPair.hostm, addr.Host) {
1516				chosenMatcherPair.hostm = append(chosenMatcherPair.hostm, addr.Host)
1517			}
1518		}
1519	
1520		// iterate each pairing of host and path matchers and
1521		// put them into a map for JSON encoding
1522		var matcherSets []map[string]caddyhttp.RequestMatcherWithError
1523		for _, mp := range matcherPairs {
1524			matcherSet := make(map[string]caddyhttp.RequestMatcherWithError)
1525			if len(mp.hostm) > 0 {
1526				matcherSet["host"] = mp.hostm
1527			}
1528			if len(mp.pathm) > 0 {
1529				matcherSet["path"] = mp.pathm
1530			}
1531			if len(matcherSet) > 0 {
1532				matcherSets = append(matcherSets, matcherSet)
1533			}
1534		}
1535	
1536		// finally, encode each of the matcher sets
1537		matcherSetsEnc := make([]caddy.ModuleMap, 0, len(matcherSets))
1538		for _, ms := range matcherSets {
1539			msEncoded, err := encodeMatcherSet(ms)
1540			if err != nil {
1541				return nil, fmt.Errorf("server block %v: %v", sblock.block.Keys, err)
1542			}
1543			matcherSetsEnc = append(matcherSetsEnc, msEncoded)
1544		}
1545	
1546		return matcherSetsEnc, nil
1547	}
