1549	func parseMatcherDefinitions(d *caddyfile.Dispenser, matchers map[string]caddy.ModuleMap) error {
1550		d.Next() // advance to the first token
1551	
1552		// this is the "name" for "named matchers"
1553		definitionName := d.Val()
1554	
1555		if _, ok := matchers[definitionName]; ok {
1556			return fmt.Errorf("matcher is defined more than once: %s", definitionName)
1557		}
1558		matchers[definitionName] = make(caddy.ModuleMap)
1559	
1560		// given a matcher name and the tokens following it, parse
1561		// the tokens as a matcher module and record it
1562		makeMatcher := func(matcherName string, tokens []caddyfile.Token) error {
1563			// create a new dispenser from the tokens
1564			dispenser := caddyfile.NewDispenser(tokens)
1565	
1566			// set the matcher name (without @) in the dispenser context so
1567			// that matcher modules can access it to use it as their name
1568			// (e.g. regexp matchers which use the name for capture groups)
1569			dispenser.SetContext(caddyfile.MatcherNameCtxKey, definitionName[1:])
1570	
1571			mod, err := caddy.GetModule("http.matchers." + matcherName)
1572			if err != nil {
1573				return fmt.Errorf("getting matcher module '%s': %v", matcherName, err)
1574			}
1575			unm, ok := mod.New().(caddyfile.Unmarshaler)
1576			if !ok {
1577				return fmt.Errorf("matcher module '%s' is not a Caddyfile unmarshaler", matcherName)
1578			}
1579			err = unm.UnmarshalCaddyfile(dispenser)
1580			if err != nil {
1581				return err
1582			}
1583	
1584			if rm, ok := unm.(caddyhttp.RequestMatcherWithError); ok {
1585				matchers[definitionName][matcherName] = caddyconfig.JSON(rm, nil)
1586				return nil
1587			}
1588			// nolint:staticcheck
1589			if rm, ok := unm.(caddyhttp.RequestMatcher); ok {
1590				matchers[definitionName][matcherName] = caddyconfig.JSON(rm, nil)
1591				return nil
1592			}
1593			return fmt.Errorf("matcher module '%s' is not a request matcher", matcherName)
1594		}
1595	
1596		// if the next token is quoted, we can assume it's not a matcher name
1597		// and that it's probably an 'expression' matcher
1598		if d.NextArg() {
1599			if d.Token().Quoted() {
1600				// since it was missing the matcher name, we insert a token
1601				// in front of the expression token itself; we use Clone() to
1602				// make the new token to keep the same the import location as
1603				// the next token, if this is within a snippet or imported file.
1604				// see https://github.com/caddyserver/caddy/issues/6287
1605				expressionToken := d.Token().Clone()
1606				expressionToken.Text = "expression"
1607				err := makeMatcher("expression", []caddyfile.Token{expressionToken, d.Token()})
1608				if err != nil {
1609					return err
1610				}
1611				return nil
1612			}
1613	
1614			// if it wasn't quoted, then we need to rewind after calling
1615			// d.NextArg() so the below properly grabs the matcher name
1616			d.Prev()
1617		}
1618	
1619		// in case there are multiple instances of the same matcher, concatenate
1620		// their tokens (we expect that UnmarshalCaddyfile should be able to
1621		// handle more than one segment); otherwise, we'd overwrite other
1622		// instances of the matcher in this set
1623		tokensByMatcherName := make(map[string][]caddyfile.Token)
1624		for nesting := d.Nesting(); d.NextArg() || d.NextBlock(nesting); {
1625			matcherName := d.Val()
1626			tokensByMatcherName[matcherName] = append(tokensByMatcherName[matcherName], d.NextSegment()...)
1627		}
1628		for matcherName, tokens := range tokensByMatcherName {
1629			err := makeMatcher(matcherName, tokens)
1630			if err != nil {
1631				return err
1632			}
1633		}
1634		return nil
1635	}
1636	
1637	func encodeMatcherSet(matchers map[string]caddyhttp.RequestMatcherWithError) (caddy.ModuleMap, error) {
1638		msEncoded := make(caddy.ModuleMap)
1639		for matcherName, val := range matchers {
1640			jsonBytes, err := json.Marshal(val)
1641			if err != nil {
1642				return nil, fmt.Errorf("marshaling matcher set %#v: %v", matchers, err)
1643			}
1644			msEncoded[matcherName] = jsonBytes
1645		}
1646		return msEncoded, nil
1647	}
