1649	// WasReplacedPlaceholderShorthand checks if a token string was
1650	// likely a replaced shorthand of the known Caddyfile placeholder
1651	// replacement outputs. Useful to prevent some user-defined map
1652	// output destinations from overlapping with one of the
1653	// predefined shorthands.
1654	func WasReplacedPlaceholderShorthand(token string) string {
1655		prev := ""
1656		for i, item := range placeholderShorthands() {
1657			// only look at every 2nd item, which is the replacement
1658			if i%2 == 0 {
1659				prev = item
1660				continue
1661			}
1662			if strings.Trim(token, "{}") == strings.Trim(item, "{}") {
1663				// we return the original shorthand so it
1664				// can be used for an error message
1665				return prev
1666			}
1667		}
1668		return ""
1669	}
