1697	// listenersUseAnyPortOtherThan returns true if there are any
1698	// listeners in addresses that use a port which is not otherPort.
1699	// Mostly borrowed from unexported method in caddyhttp package.
1700	func listenersUseAnyPortOtherThan(addresses []string, otherPort string) bool {
1701		otherPortInt, err := strconv.Atoi(otherPort)
1702		if err != nil {
1703			return false
1704		}
1705		for _, lnAddr := range addresses {
1706			laddrs, err := caddy.ParseNetworkAddress(lnAddr)
1707			if err != nil {
1708				continue
1709			}
1710			if uint(otherPortInt) > laddrs.EndPort || uint(otherPortInt) < laddrs.StartPort {
1711				return true
1712			}
1713		}
1714		return false
1715	}
