1717	func mapContains[K comparable, V any](m map[K]V, keys []K) bool {
1718		if len(m) == 0 || len(keys) == 0 {
1719			return false
1720		}
1721		for _, key := range keys {
1722			if _, ok := m[key]; ok {
1723				return true
1724			}
1725		}
1726		return false
1727	}
