1729	// specificity returns len(s) minus any wildcards (*) and
1730	// placeholders ({...}). Basically, it's a length count
1731	// that penalizes the use of wildcards and placeholders.
1732	// This is useful for comparing hostnames and paths.
1733	// However, wildcards in paths are not a sure answer to
1734	// the question of specificity. For example,
1735	// '*.example.com' is clearly less specific than
1736	// 'a.example.com', but is '/a' more or less specific
1737	// than '/a*'?
1738	func specificity(s string) int {
1739		l := len(s) - strings.Count(s, "*")
1740		for len(s) > 0 {
1741			start := strings.Index(s, "{")
1742			if start < 0 {
1743				return l
1744			}
1745			end := strings.Index(s[start:], "}") + start + 1
1746			if end <= start {
1747				return l
1748			}
1749			l -= end - start
1750			s = s[end:]
1751		}
1752		return l
1753	}
