1772	// addressWithProtocols associates a listen address with
1773	// the protocols to serve it with
1774	type addressWithProtocols struct {
1775		address   string
1776		protocols []string
1777	}
1778	
1779	// sbAddrAssociation is a mapping from a list of
1780	// addresses with protocols, and a list of server
1781	// blocks that are served on those addresses.
1782	type sbAddrAssociation struct {
1783		addressesWithProtocols []addressWithProtocols
1784		serverBlocks           []serverBlock
1785	}
1786	
1787	const (
1788		matcherPrefix = "@"
1789		namedRouteKey = "named_route"
1790	)
1791	
1792	// Interface guard
1793	var _ caddyfile.ServerType = (*ServerType)(nil)
1794

