85	// redirRespondOrder decodes the site subroute and returns the relative
86	// pipeline order of the redir (a static_response carrying status 302) and
87	// the plain respond (a static_response carrying a body). Headers are
88	// ignored.
89	func redirRespondOrder(t *testing.T, out []byte) []string {
90		t.Helper()
91		var doc struct {
92			Apps struct {
93				HTTP struct {
94					Servers map[string]struct {
95						Routes []struct {
96							Handle []struct {
97								Routes []struct {
98									Handle []struct {
99										StatusCode int    `json:"status_code"`
100										Body       string `json:"body"`
101									} `json:"handle"`
102								} `json:"routes"`
103							} `json:"handle"`
104						} `json:"routes"`
105					} `json:"servers"`
106				} `json:"http"`
107			} `json:"apps"`
108		}
109		if err := json.Unmarshal(out, &doc); err != nil {
110			t.Fatalf("unmarshaling adapted JSON: %v\n%s", err, out)
111		}
112		var order []string
113		for _, srv := range doc.Apps.HTTP.Servers {
114			for _, route := range srv.Routes {
115				for _, h := range route.Handle {
116					for _, sr := range h.Routes {
117						for _, hh := range sr.Handle {
118							if hh.StatusCode == 302 {
119								order = append(order, "redir")
120							} else if hh.Body != "" {
121								order = append(order, "respond")
122							}
123						}
124					}
125				}
126			}
127		}
128		return order
129	}
