// directiveOrderForOptions returns the directive order in effect for an
// adaptation given its options. The "order" global option stores the
// per-adaptation ordering constraints it parsed; without any constraints
// the registered package baseline is used. This never reads or writes
// shared mutable state.
func directiveOrderForOptions(options map[string]any) []string {
	if options != nil {
		if constraints, ok := options["order"].([]directiveOrderConstraint); ok && len(constraints) > 0 {
			// resolveDirectiveOrder returns an error; directiveOrderForOptions
			// is called from paths that have already validated the constraints
			// (see resolveAdaptationDirectiveOrder), so the error is unexpected.
			order, err := resolveDirectiveOrder(directiveOrder, constraints)
			if err != nil {
				panic(err)
			}
			return order
		}
	}
	return directiveOrder
}

// resolveAdaptationDirectiveOrder merges the "order" constraints collected
// for an adaptation with the package baseline directive order and returns
// the resulting total order. It is called once, before any site is parsed,
// so contradictory or cyclic constraints fail the whole adaptation with no
// partial JSON instead of affecting some sites and not others.
func resolveAdaptationDirectiveOrder(options map[string]any) ([]string, error) {
	if constraints, ok := options["order"].([]directiveOrderConstraint); ok && len(constraints) > 0 {
		return resolveDirectiveOrder(directiveOrder, constraints)
	}
	return directiveOrder, nil
}

