// The baseline contributes an edge between adjacent directives only
// while they stay in the same anchor group; the anchors themselves
// enforce cross-group ordering below. A directive relocated by a
// Before/After constraint is detached from its baseline neighbors, so
// the declaration moves it instead of contradicting the default order;
// the rank-based tiebreak below lands it as close to its anchor as the
// constraints allow.
inSameGroup := func(a, b string) bool {
	_, aFirst := firstSet[a]
	_, bFirst := firstSet[b]
	_, aLast := lastSet[a]
	_, bLast := lastSet[b]
	return aFirst == bFirst && aLast == bLast
}
for i := 1; i < len(nodes); i++ {
	prev, cur := nodes[i-1], nodes[i]
	if inSameGroup(prev, cur) {
		addEdge(prev, cur)
	}
}

// Detach each relocated directive from its baseline neighbors. This
// runs before the user edges are added so only the declarations and
// the anchor edges decide where the directive lands.
relocated := make(map[string]struct{})
for _, c := range constraints {
	if c.position == Before || c.position == After {
		relocated[c.subject] = struct{}{}
	}
}
for subject := range relocated {
	idx := slices.Index(allDirectives, subject)
	if idx > 0 {
		deleteEdge(allDirectives[idx-1], subject)
	}
	if idx+1 < len(allDirectives) {
		deleteEdge(subject, allDirectives[idx+1])
	}
}

// Every first-anchored directive precedes every non-first directive,
// and every non-last directive precedes every last-anchored directive.
// These edges fully realize the anchors, including against plugin
// directives that have no baseline position.
for _, f := range first {
	for _, n := range nodes {
		if _, isFirst := firstSet[n]; !isFirst {
			addEdge(f, n)
		}
	}
}
for _, l := range last {
	for _, n := range nodes {
		if _, isLast := lastSet[n]; !isLast {
			addEdge(n, l)
		}
	}
}

// user constraints; remember one declaration per edge so a cycle can be
// reported at a location the user can fix.
edgeOrigin := make(map[[2]string]directiveOrderConstraint)
for _, c := range constraints {
	if c.position != Before && c.position != After {
		continue
	}
	from, to := c.subject, c.anchor
	if c.position == After {
		from, to = c.anchor, c.subject
	}
	edgeOrigin[[2]string{from, to}] = c
	addEdge(from, to)
}

