// user constraints; remember one declaration per edge so a cycle can be
// reported at a location the user can fix.
edgeOrigin := make(map[[2]string]directiveOrderConstraint)
for _, c := range constraints {
	if c.position != Before && c.position != After {
		continue
	}
	from, to := c.subject, c.anchor
	if c.position == After {
		from, to = c.anchor, c.subject
	}
	edgeOrigin[[2]string{from, to}] = c
	addEdge(from, to)
}

// Each directive gets a desired position used only as a deterministic
// tiebreak among directives the graph leaves unordered. A directive
// kept in place keeps its baseline rank; a relocated one gets a slot
// immediately beside its anchor (half a rank before for Before, half a
// rank after for After), so it lands next to the anchor while the
// directives it was detached from keep their default relative order.
// These slots are propagated in a fixed order for a bounded number of
// passes, which makes the result depend solely on the graph and the
// baseline, never on the declaration order.
keys := make(map[string]float64, len(allDirectives))
for i, dir := range allDirectives {
	keys[dir] = float64(i)
}
const propagationPasses = 16
for pass := 0; pass < propagationPasses; pass++ {
	changed := false
	for _, c := range constraints {
		if c.position != Before && c.position != After {
			continue
		}
		target := keys[c.anchor] - 0.5
		if c.position == After {
			target = keys[c.anchor] + 0.5
		}
		if c.position == Before {
			if target < keys[c.subject] {
				keys[c.subject] = target
				changed = true
			}
		} else if target > keys[c.subject] {
			keys[c.subject] = target
			changed = true
		}
	}
	if !changed {
		break
	}
}

// Kahn's algorithm. Among ready directives, the one with the smallest
// desired position is emitted; exact key ties (two directives parked
// beside the same anchor) fall back to their baseline rank. Because the
// tiebreak is a pure function of the graph and the baseline, swapping
// declaration lines or import traversal order cannot change the output.
ready := make([]string, 0, len(nodes))
for _, n := range nodes {
	if indegree[n] == 0 {
		ready = append(ready, n)
	}
}
less := func(a, b string) bool {
	if keys[a] != keys[b] {
		return keys[a] < keys[b]
	}
	return ranks[a] < ranks[b]
}

