255	// applied deterministically: subjects anchored first sort before every
256	// other directive, those anchored last after every other directive, and
257	// ties within each anchor group keep the baseline order. A cycle in the
258	// constraint graph is reported as an error naming the directives involved,
259	// together with the location of a constraint that participates in the cycle.
260	func resolveDirectiveOrder(baseline []string, constraints []directiveOrderConstraint) ([]string, error) {
261		// Every directive named by a constraint participates in the graph,
262		// including directives registered without a default position (e.g.
263		// plugin directives the user is ordering for the first time). Baseline
264		// directives come first in their default order; extras are appended
265		// sorted by name so their tiebreak rank is independent of the order in
266		// which the constraint lines were written.
267		known := make(map[string]struct{}, len(baseline))
268		for _, dir := range baseline {
269			known[dir] = struct{}{}
270		}
271		var extras []string
272		seenExtra := make(map[string]struct{})
273		addKnown := func(dir string) {
274			if _, ok := known[dir]; ok {
275				return
276			}
277			if _, ok := seenExtra[dir]; ok {
278				return
279			}
280			seenExtra[dir] = struct{}{}
281			extras = append(extras, dir)
282		}
283		for _, c := range constraints {
284			addKnown(c.subject)
285			if c.anchor != "" {
286				addKnown(c.anchor)
287			}
288		}
289		sort.Strings(extras)
290	
291		// allDirectives is the baseline followed by the name-sorted extras.
292		allDirectives := append(append([]string{}, baseline...), extras...)
293	
294		// ranks give every directive a stable tiebreak position.
295		ranks := make(map[string]int, len(allDirectives))
296		for i, dir := range allDirectives {
297			ranks[dir] = i
298		}
299	
300		// anchors group directives into first / unanchored / last while keeping
301		// baseline order within each group.
302		var first, last, middle []string
303		firstSet := make(map[string]struct{})
304		lastSet := make(map[string]struct{})
305		for _, dir := range allDirectives {
306			switch {
307			case isAnchored(constraints, dir, First):
308				first = append(first, dir)
309				firstSet[dir] = struct{}{}
310			case isAnchored(constraints, dir, Last):
311				last = append(last, dir)
312				lastSet[dir] = struct{}{}
313			default:
314				middle = append(middle, dir)
315			}
316		}
317	
318		// nodes traverses the groups in first/middle/last order.
319		nodes := append(append(append([]string{}, first...), middle...), last...)
320		indegree := make(map[string]int, len(nodes))
321		successors := make(map[string]map[string]struct{}, len(nodes))
322		addEdge := func(from, to string) {
323			if from == to {
324				return
325			}
326			if successors[from] == nil {
327				successors[from] = make(map[string]struct{})
328			}
329			if _, ok := successors[from][to]; !ok {
330				successors[from][to] = struct{}{}
331				indegree[to]++
332			}
333		}
334	
