package httpcaddyfile

import (
	"fmt"
	"testing"
)

func probeOrder(t *testing.T, constraints []directiveOrderConstraint, extras []string) []string {
	t.Helper()
	base := append([]string{}, defaultDirectiveOrder...)
	base = append(base, extras...)
	got, err := resolveDirectiveOrder(base, constraints)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	return got
}

func c(subject string, pos Positional, anchor string) directiveOrderConstraint {
	return directiveOrderConstraint{subject: subject, position: pos, anchor: anchor, file: "Caddyfile", line: 1}
}

func TestProbeOrder(t *testing.T) {
	// 1. respond before redir
	got := probeOrder(t, []directiveOrderConstraint{c("respond", Before, "redir")}, nil)
	idx := func(s string) int {
		for i, d := range got {
			if d == s {
				return i
			}
		}
		return -1
	}
	if idx("respond") != idx("redir")-1 {
		t.Fatalf("respond not immediately before redir:\n%v", got)
	}
	// header should still precede redir and come before respond
	if !(idx("header") < idx("respond") && idx("respond") < idx("redir")) {
		t.Fatalf("header/respond/redir wrong: header=%d respond=%d redir=%d", idx("header"), idx("respond"), idx("redir"))
	}
	// vars still early, file_server still after redir
	if !(idx("vars") < idx("header") && idx("file_server") > idx("redir")) {
		t.Fatalf("default neighbors wrong")
	}
	fmt.Println("CASE1", got)

	// 2. line swap: respond before redir vs same thing, reversed declarations list
	got2 := probeOrder(t, []directiveOrderConstraint{
		c("respond", Before, "redir"),
		c("header", After, "respond"),
	}, nil)
	got3 := probeOrder(t, []directiveOrderConstraint{
		c("header", After, "respond"),
		c("respond", Before, "redir"),
	}, nil)
	if fmt.Sprint(got2) != fmt.Sprint(got3) {
		t.Fatalf("line swap changed order:\n%v\n%v", got2, got3)
	}
	fmt.Println("CASE2", got2)

	// 3. plugin directive (extra) after vars
	got4 := probeOrder(t, []directiveOrderConstraint{c("myplug", After, "vars")}, []string{"myplug"})
	i4 := func(s string) int {
		for i, d := range got4 {
			if d == s {
				return i
			}
		}
		return -1
	}
	if !(i4("vars") < i4("myplug") && i4("myplug") < i4("map") == false) {
		// myplug after vars; map precedes vars in baseline
	}
	if !(i4("myplug") == i4("vars")+1) {
		t.Fatalf("plugin not right after vars: vars=%d myplug=%d map=%d\n%v", i4("vars"), i4("myplug"), i4("map"), got4)
	}
	fmt.Println("CASE3 myplug at", i4("myplug"))

	// 4. chain: x after vars, y after x (extras)
	got5 := probeOrder(t, []directiveOrderConstraint{
		c("myplugX", After, "vars"),
		c("myplugY", After, "myplugX"),
	}, []string{"myplugX", "myplugY"})
	ix := -1
	for i, d := range got5 {
		if d == "myplugX" {
			ix = i
		}
		if d == "myplugY" && (ix < 0 || i != ix+1) {
			t.Fatalf("chain not adjacent")
		}
	}
	fmt.Println("CASE5", got5)

	// 5. 3-cycle must error
	_, err := resolveDirectiveOrder(defaultDirectiveOrder, []directiveOrderConstraint{
		c("redir", Before, "header"),
		c("header", Before, "respond"),
		c("respond", Before, "redir"),
	})
	if err == nil {
		t.Fatal("expected cycle error")
	}
	fmt.Println("CASE5 err:", err)

	// 6. self relation must error
	_, err = resolveDirectiveOrder(defaultDirectiveOrder, []directiveOrderConstraint{
		c("redir", Before, "redir"),
	})
	if err == nil {
		t.Fatal("expected self cycle error")
	}
	fmt.Println("CASE6 err:", err)

	// 7. first + last
	got7 := probeOrder(t, []directiveOrderConstraint{
		c("respond", First, ""),
		c("redir", Last, ""),
	}, nil)
	if got7[0] != "respond" || got7[len(got7)-1] != "redir" {
		t.Fatalf("first/last wrong: %v", got7)
	}
	fmt.Println("CASE7 first", got7[0], "last", got7[len(got7)-1])

	// 8. same anchor, multiple before - deterministic
	got8a := probeOrder(t, []directiveOrderConstraint{
		c("respond", Before, "header"),
		c("file_server", Before, "header"),
	}, nil)
	got8b := probeOrder(t, []directiveOrderConstraint{
		c("file_server", Before, "header"),
		c("respond", Before, "header"),
	}, nil)
	if fmt.Sprint(got8a) != fmt.Sprint(got8b) {
		t.Fatalf("same-anchor pair not stable:\n%v\n%v", got8a, got8b)
	}
	fmt.Println("CASE8", got8a)
}

