func adapt(t *testing.T, body string) ([]byte, error) {
	t.Helper()
	a := caddyfile.Adapter{ServerType: ServerType{}}
	out, _, err := a.Adapt([]byte(body), nil)
	return out, err
}

func TestZZE2E(t *testing.T) {
	// 1. before/after reorder
	o1, err := adapt(t, "{\n\torder respond before redir\n}\nexample.com {\n\tredir /a /b\n\trespond \"X\"\n}\n")
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Index(o1, []byte(`"body": "X"`)) > bytes.Index(o1, []byte(`"status_code": "302"`)) {
		t.Fatal("respond should precede redir")
	}

	// 2. after variant and line-swapped multi constraints produce identical JSON
	bodies := []string{
		"{\n\torder header after respond\n\torder respond before redir\n}\nexample.com {\n\theader x y\n\tredir /a /b\n\trespond \"X\"\n}\n",
		"{\n\torder respond before redir\n\torder header after respond\n}\nexample.com {\n\theader x y\n\tredir /a /b\n\trespond \"X\"\n}\n",
	}
	var prev []byte
	for i, b := range bodies {
		out, err := adapt(t, b)
		if err != nil {
			t.Fatalf("%d: %v", i, err)
		}
		if prev != nil && !bytes.Equal(prev, out) {
			t.Fatalf("line swap changed JSON (%d)", i)
		}
		prev = out
	}

	// 3. cycle
	_, err = adapt(t, "{\n\torder redir before header\n\torder header before respond\n\torder respond before redir\n}\nexample.com {\n\tredir /a /b\n}\n")
	if err == nil || !strings.Contains(err.Error(), "cyclic") || !strings.Contains(err.Error(), "Caddyfile:") {
		t.Fatalf("cycle: %v", err)
	}

	// 4. contradictory pair
	_, err = adapt(t, "{\n\torder respond before redir\n\torder redir before respond\n}\nexample.com {\n\tredir /a /b\n}\n")
	if err == nil || !strings.Contains(err.Error(), "conflicting") {
		t.Fatalf("contradiction: %v", err)
	}

	// 5. unregistered subject and anchor
	for _, b := range []string{
		"{\n\torder nosuchdir before redir\n}\nexample.com {\n\tredir /a /b\n}\n",
		"{\n\torder respond before nosuchdir\n}\nexample.com {\n\tredir /a /b\n}\n",
	} {
		if _, err := adapt(t, b); err == nil || !strings.Contains(err.Error(), "not a registered directive") {
			t.Fatalf("unregistered: %v", err)
		}
	}

