	b6 := "{\n\torder respond before redir\n}\nexample.com {\n\thandle {\n\t\tredir /a /b\n\t\trespond \"INNER\"\n\t}\n}\n"
	o6, err := adapt(t, b6)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Index(o6, []byte(`"body": "INNER"`)) < bytes.Index(o6, []byte(`"status_code": "302"`)) {
		t.Fatal("inner handle should keep textual redir-before-respond order")
	}

	// 7. route keeps textual order
	b7 := "{\n\torder respond before redir\n}\nexample.com {\n\troute {\n\t\tredir /a /b\n\t\trespond \"RINNER\"\n\t}\n}\n"
	o7, err := adapt(t, b7)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Index(o7, []byte(`"body": "RINNER"`)) < bytes.Index(o7, []byte(`"status_code": "302"`)) {
		t.Fatal("inner route should keep textual redir-before-respond order")
	}

