	good := []byte("example.com {\n\tredir /a /b\n\trespond \"OK\"\n}\n")
	out, _, err := a.Adapt(good, nil)
	if err != nil {
		t.Fatalf("reuse after fail: %v", err)
	}
	if !bytes.Contains(out, []byte("OK")) {
		t.Fatal("missing body")
	}
	if _, _, err := a.Adapt(bad, nil); err == nil {
		t.Fatal("expected re-fail")
	}
}

