// buildSubroute turns the config values, which are expected to be routes
// into a clean and orderly subroute that has all the routes within it.
// order is the directive ordering in effect for the current adaptation.
// sortByOrder arranges the routes per the global order and is used only
// for each site's top-level chain; nested scopes (route, handle and their
// children) pass false to keep their local order. validateOrder reports an
// error for a directive that is not a recognized ordered HTTP handler;
// route blocks intentionally skip it because they are the documented
// escape hatch for otherwise-unordered directives.
func buildSubroute(routes []ConfigValue, groupCounter counter, sortByOrder, validateOrder bool, order []string) (*caddyhttp.Subroute, error) {
	if sortByOrder || validateOrder {
		for _, val := range routes {
			if !slices.Contains(order, val.directive) {
				return nil, fmt.Errorf("directive '%s' is not an ordered HTTP handler, so it cannot be used here - try placing within a route block or using the order global option", val.directive)
			}
		}
	}

	if sortByOrder {
		sortRoutes(routes, order)
	}

